export function canPartition(values          )          {
const sum=values.reduce((a,b)=>a+b,0);if(sum%2)return false;const target=sum/2;const possible          =Array(target+1).fill(false);possible[0]=true;for(const x of values)for(let t=target;t>=x;t--)possible[t]=possible[t]||possible[t-x];return possible[target];
}

